        for i in range(self.retry_count):
            try:
                return fn(*args, **kwargs)
            except Exception as e:
                self.log.warning('retry %d: %s', i, e)
                if i == self.retry_count - 1:
                    raise

class K8sClient(LoggingMixin, RetryMixin):
    def __init__(self, endpoint: str):
        self.endpoint = endpoint

    def get_pods(self):
        return self.with_retry(self._fetch_pods)

    def _fetch_pods(self):
        self.log.info('GET %s/api/v1/pods', self.endpoint)
        return {'items': []}

client = K8sClient('https://k8s.local:6443')
result = client.get_pods()
print(f'pods ok: {len(result["items"])} items')
